using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;
namespace FashionFit.Editor {
 public static class SurfacePolishPreview {
  public static void RunBatch(){GameObject root=null;try{string folder=Path.GetFullPath("Verification/SurfacePolish");Directory.CreateDirectory(folder);root=new GameObject("Surface repairs preview");var app=root.AddComponent<FashionFitApp>();typeof(FashionFitApp).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,null);if(!app.Ready)throw new Exception(app.FatalError);app.MaterialLab.ShowReadings=false;var avatar=app.PoseStudio.Rigs[0].Avatar;Capture(app.Player.View,avatar.transform.TransformPoint(new Vector3(.70f,1.4f,1.85f)),avatar.transform.TransformPoint(new Vector3(0,1.25f,0)),folder+"/BeforeShirt.png");app.PoseStudio.Wearables[0].Clear();var timer=System.Diagnostics.Stopwatch.StartNew();var mesh=ContinuousShirtShell.Build(avatar,false);timer.Stop();var mat=new Material(Resources.Load<Shader>("Runway/DressFabric"));mat.SetColor("_Color",new Color(.82f,.78f,.66f));var go=new GameObject("New seamless shirt");go.transform.SetParent(avatar.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=mat;Capture(app.Player.View,avatar.transform.TransformPoint(new Vector3(.70f,1.4f,1.85f)),avatar.transform.TransformPoint(new Vector3(0,1.25f,0)),folder+"/RawShirt.png");using(var writer=new BinaryWriter(File.Create(folder+"/RawMesh.bin"))){writer.Write(mesh.vertexCount);foreach(var point in mesh.vertices){writer.Write(point.x);writer.Write(point.y);writer.Write(point.z);}writer.Write(mesh.triangles.Length);foreach(int index in mesh.triangles)writer.Write(index);}UnityEngine.Object.DestroyImmediate(go.GetComponent<MeshRenderer>());UnityEngine.Object.DestroyImmediate(go.GetComponent<MeshFilter>());var driver=go.AddComponent<BodyBoundSurface>();driver.Initialize(avatar,mesh,mat,"Female");for(int i=0;i<12;i++)driver.Step(1f/60);Capture(app.Player.View,avatar.transform.TransformPoint(new Vector3(.70f,1.4f,1.85f)),avatar.transform.TransformPoint(new Vector3(0,1.25f,0)),folder+"/AfterShirt.png");Capture(app.Player.View,avatar.transform.TransformPoint(new Vector3(.9f,1.4f,.42f)),avatar.transform.TransformPoint(new Vector3(0,1.28f,0)),folder+"/AfterSide.png");File.WriteAllText(folder+"/mesh.json","{\"vertices\":"+mesh.vertexCount+",\"triangles\":"+mesh.triangles.Length/3+",\"buildMs\":"+timer.Elapsed.TotalMilliseconds.ToString(System.Globalization.CultureInfo.InvariantCulture)+"}");UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(mat);EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);if(root)UnityEngine.Object.DestroyImmediate(root);EditorApplication.Exit(1);}}
  static void Capture(Camera c,Vector3 p,Vector3 target,string path){c.rect=new Rect(0,0,1,1);c.transform.position=p;c.transform.LookAt(target);var rt=new RenderTexture(1100,1100,24);var t=new Texture2D(1100,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;t.ReadPixels(new Rect(0,0,1100,1100),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}}
 }
